# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C11（v9 新域 8 簇+直答：消费金融/食品安全/电动车安全/城市拥堵/老字号非遗/体育饭圈/水资源/塑料污染）"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "概念形成": ["概念形成", "原型理论", "样例理论", "概念是怎么形成的"],'
    new_c = '''    "消费金融": ["网贷这么容易借到", "网贷", "信用卡透支", "缺钱的时候",
                "借钱消费", "超前消费", "理性消费怎么平衡", "网贷陷阱",
                "消费金融"],
    "食品安全": ["食品添加剂", "添加剂", "预制菜", "科技与狠活",
                "食品怎么保存", "谈添加剂色变", "过度恐慌", "吃得放心",
                "食品安全"],
    "电动车安全": ["电动车起火", "起火事故", "进楼充电", "电动车进楼",
                "没电动车", "接送孩子", "管的太多", "不让人活了",
                "电动车怎么用", "城市出行", "电动车"],
    "城市拥堵": ["城市越来越堵", "停车位", "不买车", "公共交通",
                "限号限行", "治标不治本", "缓解城市拥堵", "城市拥堵",
                "买车还是"],
    "老字号非遗": ["老字号", "越来越少", "非遗手艺", "没人学",
                "老东西过时了", "淘汰不是自然", "非遗靠补贴", "补贴养着",
                "焕发新生", "非遗传承", "传承和创新", "非遗"],
    "体育饭圈": ["体育圈", "饭圈化", "接代言", "运动员", "粉丝支持",
                "成绩不好被骂", "体育回归", "回归竞技", "面对舆论"],
    "水资源": ["水资源", "越来越紧张", "水费涨价", "水到处都有",
                "多用点水", "节约用水", "水资源怎么分配", "分配才公平"],
    "塑料污染": ["限塑令", "外卖塑料", "塑料垃圾", "不用塑料",
                "塑料袋收费", "变相赚钱", "减少塑料污染", "塑料污染",
                "限塑"],'''
    assert anchor_c in src, "cluster anchor missing"
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'
    new_d = '''    "消费金融": "网贷容易借到、信用卡透支上瘾，是『即时满足』vs『远期代价』的矛盾——平台把借钱变得比取钱还容易（手机点两下到账），但代价（利息/征信/催收）藏在后面。真相：①网贷为什么容易借——不是平台善良，是商业模式：放贷赚利息，借得越多赚越多，所以它拼命降低门槛（无抵押/秒到账/广告轰炸），『容易借』是获客策略不是福利；②信用卡透支是不是坑——看用不用得明白：免息期内还清=短期周转工具（没问题），只还最低还款/分期=复利陷阱（日息万五折算年化18%+），『坑』在透支习惯不在卡本身；③借钱消费有错吗——错不在借钱在『消费的性质』：借钱买必需品（应急/医疗/教育）是杠杆，借钱买非必需（新款手机/旅游/攀比）是透支未来，区别是『投资自己还是消费虚荣』。避坑：①只借『应急的钱』——生病/救急可用，日常消费不进借贷；②看清年化利率——不只看日息月息（日息0.05%×365=18.25%，远超存款），警惕『低息』话术（手续费/服务费都是利息）；③还款纪律——每月还款额≤收入30%，『以贷养贷』是死亡螺旋（利息滚雪球）立刻止损求助（家人/机构）；④超前消费和理性消费的平衡——超前用在『资产/能力』（买房上学），理性用在『消费/享受』（量入为出），原则：花未来的钱要买未来的价值",
    "食品安全": "食品添加剂被当成『科技与狠活』，是『信息恐慌』vs『科学事实』的矛盾——添加剂名字吓人（苯甲酸钠/山梨酸钾），但『添加剂』和『违规添加物』是两回事。真相：①添加剂安不安全——看标准：国家标准（GB2760）允许的添加剂都经过安全评估（毒理实验/每日允许摄入量），『剂量决定毒性』（盐吃多了也中毒），合规添加≠有害；②预制菜是不是科技与狠活——预制菜是工业化生产（中央厨房/冷链/标准化），『狠活』指违规添加（防腐剂超量/劣质原料），正规预制菜（大厂/冷链）和饭店现炒的差距主要在口感和新鲜度，不在安全性；③没有添加剂食品怎么保存——靠物理手段（冷藏/真空/高温杀菌）成本高保质短，添加剂（防腐/抗氧化）是食品工业降低浪费的手段，『零添加』≠更安全（可能靠高糖高盐防腐）；④谈添加剂色变是不是过度恐慌——是：恐慌来自信息差（化学名吓人+谣言放大），但『乱添加』确实存在（小作坊/黑心商家）——该怕的是『违规』不是『合规』。吃得放心的现实路径：①看配料表——前三位是主要成分（添加剂排名靠后含量低），识别『高盐高糖高油』比识别添加剂更重要（健康杀手是油盐糖不是防腐剂）；②大厂+正规渠道——供应链规范比『零添加』标签可靠；③多样饮食——不长期只吃一种加工食品，天然食材为主、加工食品为辅，风险自然分散",
    "电动车安全": "电动车起火事故多、进楼充电被禁，是『出行刚需』vs『公共安全』的矛盾——电动车便宜方便（接送孩子/上班通勤），但电池（锂电池）一旦热失控起火极快（几秒到几分钟），楼道充电堵死逃生通道。真相：①为什么起火多——不是电动车本身危险，是『电池质量+充电习惯』：劣质电池（小厂/改装）、过度充电、飞线充电、楼道充电（高温/碰撞/进水引发热失控），正规电池+规范充电事故率极低；②进楼充电该不该禁——该禁：楼道/室内充电一旦起火，浓烟封死逃生通道（电动车火灾致死主因是烟不是火），禁的是『危险充电方式』不是电动车本身；③没电动车怎么接送孩子上班——公共交通/班车/拼车/更近的学校（政策要配套：充电桩/停放区/公交优化），『禁了不解决替代』是懒政，但『为方便赌命』不值；④管的太多不让人活——管的是安全底线（充电规范/电池标准），不是出行自由，规范电动车（新国标/合格电池/集中充电）恰恰让电动车能长期骑。安全使用：①电池——买合格产品（新国标/3C认证），不改装不加装（改装是起火最大来源）；②充电——用原装充电器/集中充电桩，不过夜充电不飞线；③停放——不进楼不入户不堵消防通道；④老化——电池2-3年衰减及时换（鼓包/续航骤降=危险信号）",
    "城市拥堵": "城市越来越堵、停车位永远不够，是『小汽车优先』vs『有限道路资源』的矛盾——车多路少是硬约束（城市道路面积固定），每个人都要开车=谁都动不了。真相：①为什么越来越堵——三因素：汽车保有量增长（买车门槛降）、城市单中心扩张（通勤距离拉长）、路网扩容跟不上（修路速度<买车速度），『修更多路』治标（诱导更多车=诱导需求，路越修越堵）；②停车位为什么不够——停车是『免费/低价』被过度使用（路边免费停=把公共空间当私家车库），车位配建标准滞后（老小区没规划），供需失衡被免费政策放大；③不买车公共交通够用吗——部分够：一线城市地铁公交覆盖已可替代，但『最后一公里』/郊区通勤/带孩子多场景仍不便——公共交通要补的是『便利性』不是『有没有』；④限号限行治标不治本——对：限行只是『总量控制』（少部分车不让上路），不解决『为什么必须开车』（公交不便/停车难/通勤远），治本在改变出行结构。缓解的现实路径：①出行结构——通勤用公交地铁（成本低于开车：油费+停车费+时间），短途步行骑行；②错峰——弹性工作制/错峰上下学，削平高峰；③停车管理——收费+共享（闲置车位错时出租），用价格让车位流动；④城市结构——多中心/职住平衡（上班离住近，长期治本）；⑤心态——堵车是城市化的代价，接受『快不了的部分』，能选的是『换一种方式』",
    "老字号非遗": "老字号越来越少、非遗手艺没人学，是『传统价值』vs『市场生存』的矛盾——老字号承载记忆和手艺（配方/工艺/匠心），但市场变了（口味/渠道/消费习惯），『酒香不怕巷子深』失效了。真相：①老字号为什么少——不是『不好』是『不适配』：老工艺成本高（手工慢）、老产品不迭代（年轻人不吃）、老渠道没触达（只做线下老顾客），市场用脚投票（不买账=倒闭），但『倒闭』不等于『没价值』（价值在文化记忆，生存靠市场适配）；②老东西过时了淘汰不是自然吗——部分自然：不适应市场的产品淘汰是规律（任何时代都有品牌兴衰），但『老字号』不是普通商品（文化资产/城市记忆/手艺传承），值得『抢救性保护』（非遗名录/传承人补贴/进校园），保护的是手艺和文化不是亏损企业；③非遗靠补贴养着有意义吗——有意义但不够：补贴保『生存』（传承人饿不死才能传艺），不保『活力』（要有人买/有人学才可持续），『输血』之外要『造血』（市场化运营）；④没人学怎么办——年轻人不学的根因是『学艺没前途』（收入低/出路窄），解决靠『让手艺值钱』（非遗IP化/文旅结合/高端定制），不是道德绑架（别用『老祖宗的东西』压人）。焕发新生：①产品创新——老配方+新口味（低糖/便携/新包装），老手艺+新场景（汉服/文创/体验课）；②渠道——线上（短视频/直播讲手艺故事）、联名（老字号×新品牌跨界出圈）；③经营——老店守品质，新店拓市场（分品牌/分产品线）；④传承——传承人带徒弟（给编制/给收入），进校园（兴趣课/研学），让年轻人『学得起也养得起自己』。核心：传统不是供起来的文物，是活着的生意——保护它活，不如让它自己活得下去",
    "体育饭圈": "体育圈饭圈化、运动员被当偶像，是『竞技精神』vs『粉丝文化』的矛盾——体育本是看实力（赢就是赢输就是输），饭圈把它变成『只看我偶像』（无脑护/互相撕/刷数据）。真相：①体育圈为什么饭圈化——流量逻辑：运动员成绩好→有故事（颜值/逆袭/性格）→媒体造星→粉丝追星（把运动员当偶像），商业价值（代言/流量）驱动下『体育明星』越来越像『娱乐明星』；②运动员该不该接代言——该接：运动员职业寿命短（黄金期5-10年），代言是合理收入（也是运动队经费来源），问题不在『接』在『怎么接』（接劣质产品/影响训练=错，正常代言没问题）；③粉丝支持有错吗——没错：支持是动力（主场氛围/精神鼓励），错的是『无脑支持』（赢了吹输了骂、骂对手、撕教练、刷票控评），支持的正解是『尊重比赛结果』；④成绩不好被骂是不是应该——不应该：运动员比谁都想要成绩（训练付出是外人看不到的），骂解决不了问题（只有压力），批评和辱骂有边界（批评技术是专业讨论，辱骂人格是网暴）。回归竞技：①媒体/平台——少炒作私生活多报道比赛本身；②运动员——用成绩说话，专注训练（成绩是最大的流量）；③粉丝——支持方式：买票看比赛/为精彩鼓掌/输了给鼓励，『爱运动员就爱他的比赛，不是爱他的周边』；④制度——饭圈打榜/控评/集资进体育圈要管（体育是竞技不是选秀）",
    "水资源": "水资源越来越紧张、水费涨价，是『水的价值』vs『取用习惯』的矛盾——地球70%是水但淡水只有2.5%（能用的江河湖泊地下水更少），人口增长+工业农业用水激增，『水多』是错觉（能用的淡水紧张）。真相：①为什么越来越紧张——需求端：人口增长（多一个人多一份水）、工业农业（生产食物/商品都耗水：1公斤牛肉耗水1.5万升）、城市化（城市人均用水>农村）；供给端：污染（能用的水变脏）、气候变化（干旱频发）、地下水超采（水位下降）；②水到处都有怎么会缺——『有』≠『能用』：海水不能直接喝（淡化贵）、脏水不能直接用（处理贵）、地下水位下降（抽不出来了），缺的是『干净的淡水』不是『水』；③我多用点水有什么关系——有关系：城市供水是集中系统（你家水龙头连着水库），人人多10%就是整个城市的缺口，而且水有成本（取水/净化/输送/污水处理，水价远低于成本）；④水费涨价合理吗——合理但要说清：水价含资源费+处理费+输送费（你现在付的连成本都不够，靠补贴），涨价倒逼节约（价格信号：贵了才珍惜）+支撑管网维护（漏损修复），但民生用水要有阶梯保护（基本用量低价，超量高价）——涨价保护的是『水够用』不是『赚你钱』。节约的现实路径：①日常——关紧水龙头/洗澡快一点/洗菜水冲厕所（一水多用），这些小事每户每月省几吨；②农业工业（大头）——滴灌替代漫灌（省70%）、工业水循环（这是节约的主战场，个人节水是态度）；③制度——阶梯水价（基本量低价/超量高价）、污水再生（中水冲厕浇灌）、雨水收集；④心态——节水不是抠门是『把水留给未来』（缺水地区一盆水洗全家，我们不是水多，是还没缺到那份上）",
    "塑料污染": "限塑令效果不好、塑料垃圾成山，是『塑料便利』vs『环境代价』的矛盾——塑料便宜轻便防水（包装/外卖/购物），但几乎不降解（自然分解要数百年），烧了污染空气埋了占土地漂海里毒害生物（微塑料已进入食物链）。真相：①限塑令为什么效果不好——限塑令限的是『免费塑料袋』（超市收费/禁超薄袋），但需求没消失：收费塑料袋变成『可降解』（很多是『伪降解』/降解条件苛刻）、外卖快递塑料包装没被覆盖（新业态绕过了限塑）、替代品贵（纸袋布袋成本高消费者不愿买）；②不用塑料外卖怎么送——可循环餐具（押金回收/共享餐盒）、纸质包装（部分品类）、自备餐具（到店吃/带饭盒），『不用塑料』不是回到原始，是换体系（循环经济：用还的不用扔的）；③塑料袋收费变相赚钱吗——部分：超市赚了袋钱（几毛成本几分），但收费的核心目的是『减少使用』（价格杠杆：贵了少用/自备袋），效果确实有（自带袋的人多了），问题是力度不够（几毛钱太便宜）。减少塑料的现实路径：①源头减量——自带袋/自带杯（咖啡/奶茶）、买大包装（少小包装）、拒绝过度包装（网购选简易装）；②循环替代——可重复用品（不锈钢吸管/玻璃饭盒）替代一次性、押金制（饮料瓶回收返钱）；③分类回收——塑料洗干净再扔（脏塑料无法回收）、认清回收标志（PET可回收/其他难回收）；④制度——禁超薄袋/塑料吸管、外卖平台责任（环保选项/可循环餐具）、生产者责任（包装减量设计）；⑤心态——别等制度也别只骂制度，个人每少用一个塑料袋都是减少一个几百年不降解的垃圾",
    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'''
    assert anchor_d in src, "daily anchor missing"
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

